def tasa_seleccion(decisiones, grupos, g):
    del_grupo = [d for d, x in zip(decisiones, grupos) if x == g]
    favorables = 0   # ← cambia esta línea: cuántas de del_grupo son «apta»
    return favorables / len(del_grupo)

